/* Generated by safe ES module refactor from the existing js/main.js implementation. */

import * as Core from "../core/index.js";
import { verifyOwnerAccess } from "../core/guards.js";
import { readObjectValue, toggleControlVisibility } from "../core/utils.js";
import { closeModal, openDeleteConfirmation, openModal, openOrderConfirmation } from "../ui/modal.js";
import { createBadge, createCell } from "../ui/table.js";

export function updateOwnerUi(isOwner) {
  toggleControlVisibility(document.getElementById("OwnerDBBtn"), isOwner);
  toggleControlVisibility(document.getElementById("openCreateAdminBtn"), isOwner);
}

export function openUserEditModal(id, plan, expiryIso, isBanned, username) {
  const idField = document.getElementById("editUserId");
  const planField = document.getElementById("editPlan");
  const expiryField = document.getElementById("editExpiry");
  const banField = document.getElementById("editBanStatus");
  const form = document.getElementById("adminEditForm");
  const ownerCache = Core.getOwnerAccessCache();

  if (idField) idField.value = String(id);
  if (planField) planField.value = String(plan || "");
  if (expiryField) expiryField.value = Core.toDatetimeLocal(expiryIso);
  if (banField) banField.value = isBanned ? "true" : "false";

  let deleteBtn = document.getElementById("modalDeleteUserBtn");
  if (form && ownerCache && ownerCache.isOwner) {
    if (!deleteBtn) {
      deleteBtn = document.createElement("button");
      deleteBtn.id = "modalDeleteUserBtn";
      deleteBtn.type = "button";
      deleteBtn.className = "btn btn-outline btn-db-delete mt-15 btn-full";
      form.appendChild(deleteBtn);
    }

    deleteBtn.textContent = "Permanently Delete Record";
    deleteBtn.style.display = "block";
    deleteBtn.onclick = () => {
      closeModal("editModal");
      deleteUser(id, username);
    };
  } else if (deleteBtn) {
    deleteBtn.style.display = "none";
  }

  openModal("editModal");
}

export async function saveUserEdit() {
  const userId = Number(document.getElementById("editUserId")?.value || 0);
  const plan = String(document.getElementById("editPlan")?.value || "").trim();
  const expiryTime = Core.toIsoOrNullFromDatetimeLocal(document.getElementById("editExpiry")?.value || "");
  const isBanned = document.getElementById("editBanStatus")?.value === "true";

  if (userId <= 0 || !plan) {
    Core.showMessage("User ID and plan are required.", "error");
    return;
  }

  Core.showLoader("Saving changes...");

  try {
    const result = await Core.requestJson("/api/admin/user/update", {
      method: "PUT",
      headers: Core.getAuthHeader(),
      body: { userId, plan, expiryTime, isBanned }
    });

    Core.hideLoader();
    if (Core.handleAdminAuthFailure(result.status)) return;
    if (!result.ok) {
      Core.showMessage(Core.extractErrorMessage(result.data, "Failed to update user."), "error");
      return;
    }

    closeModal("editModal");
    Core.showMessage("User updated successfully.", "success");
    await loadAdminDash();
  } catch (err) {
    Core.hideLoader();
    Core.showMessage(Core.isAbortError(err) ? "Request timed out. Try again." : "Server error.", "error");
  }
}

export function deleteUser(userId, username) {
  openDeleteConfirmation(String(username || `User #${userId}`), async () => {
    Core.showLoader("Deleting user...");

    try {
      const result = await Core.requestJson(`/api/admin/user/delete/${userId}`, {
        method: "DELETE",
        headers: Core.getAuthHeader()
      });

      Core.hideLoader();
      if (Core.handleAdminAuthFailure(result.status)) return;
      if (!result.ok) {
        Core.showMessage(Core.extractErrorMessage(result.data, "Failed to delete user."), "error");
        return;
      }

      Core.showMessage(`User ${username} deleted successfully.`, "success");
      await loadAdminDash();
    } catch (err) {
      Core.hideLoader();
      Core.showMessage("Server error while deleting user.", "error");
    }
  });
}

export function renderUsersTable(users) {
  const tbody = document.getElementById("OwnerDBBody");
  if (!tbody) return;
  tbody.innerHTML = "";

  users.forEach((user) => {
    const id = Number(readObjectValue(user, ["id", "Id"], 0));
    const username = String(readObjectValue(user, ["username", "Username"], ""));
    const plan = String(readObjectValue(user, ["plan", "Plan"], "free"));
    const expiry = readObjectValue(user, ["expiryTime", "ExpiryTime"], null);
    const isBanned = Boolean(readObjectValue(user, ["isBanned", "IsBanned"], false));

    const row = document.createElement("tr");
    row.appendChild(createCell(id > 0 ? `#${id}` : "-"));
    row.appendChild(createCell(username));
    row.appendChild(createCell(plan));
    row.appendChild(createCell(Core.formatDateTime(expiry)));

    const statusCell = document.createElement("td");
    statusCell.appendChild(createBadge(isBanned ? "Banned" : "Active", isBanned ? "bad" : "good"));
    row.appendChild(statusCell);

    const actionCell = document.createElement("td");
    actionCell.className = "row-actions";
    const editBtn = document.createElement("button");
    editBtn.type = "button";
    editBtn.className = "btn-danger";
    editBtn.textContent = "Edit";
    editBtn.addEventListener("click", () => openUserEditModal(id, plan, expiry, isBanned, username));
    actionCell.appendChild(editBtn);
    row.appendChild(actionCell);

    tbody.appendChild(row);
  });
}

export async function loadAdminDash() {
  const ordersSection = document.getElementById("ordersSection");
  if (ordersSection) ordersSection.style.display = "block";

  Core.showLoader("Loading dashboard...");

  try {
    const isOwner = await verifyOwnerAccess();
    updateOwnerUi(isOwner);

    const result = await Core.requestJson("/api/admin/users", {
      method: "GET",
      headers: Core.getAuthHeader()
    });

    if (Core.handleAdminAuthFailure(result.status)) {
      Core.hideLoader();
      return;
    }

    if (!result.ok) {
      Core.hideLoader();
      Core.showMessage(Core.extractErrorMessage(result.data, "Failed to load users."), "error");
      return;
    }

    renderUsersTable(Core.normalizeUsersPayload(result.data));
    await loadPendingOrders();
    Core.hideLoader();
  } catch (err) {
    Core.hideLoader();
    Core.showMessage(Core.isAbortError(err) ? "Request timed out. Try again." : "Failed to load dashboard.", "error");
  }
}

export async function loadPendingOrders() {
  const tbody = document.getElementById("OrdersTableBody");
  if (!tbody) return;

  try {
    const result = await Core.requestJson("/api/admin/orders/pending", {
      method: "GET",
      headers: Core.getAuthHeader()
    });

    if (Core.handleAdminAuthFailure(result.status)) return;

    const orders = Core.normalizeListPayload(result.data, ["orders", "Orders", "pendingOrders", "PendingOrders"]);
    if (!result.ok || orders.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" class="text-center muted">No pending orders.</td></tr>';
      return;
    }

    tbody.innerHTML = "";
    orders.forEach((order) => {
      const row = document.createElement("tr");

      // 🔥 FIX: Ab JSON case-sensitive issue nahi aayega, sab data correctly fetch hoga
      const orderId = readObjectValue(order, ["id", "Id"]);

      row.appendChild(createCell(`#${orderId}`));
      row.appendChild(createCell(readObjectValue(order, ["username", "Username"]), "fw-bold text-white"));
      row.appendChild(createCell(readObjectValue(order, ["discordId", "DiscordId"], "None")));

      const planStr = String(readObjectValue(order, ["plan", "Plan"], "")).toUpperCase();
      const daysVal = readObjectValue(order, ["days", "Days"], 0);
      row.appendChild(createCell(`${planStr} (${daysVal}D)`));

      row.appendChild(createCell(readObjectValue(order, ["amount", "Amount"], "-"), "text-gold fw-bold"));
      row.appendChild(createCell(readObjectValue(order, ["txnId", "TxnId"], "-"), "font-orbitron text-secondary"));

      const actionCell = document.createElement("td");
      actionCell.className = "row-actions";

      const approveBtn = document.createElement("button");
      approveBtn.type = "button";
      approveBtn.className = "btn-success";
      approveBtn.innerHTML = "✅ Approve"; // Emoji add kiya
      approveBtn.style.padding = "5px 12px";
      approveBtn.addEventListener("click", () => processOrder(orderId, "approve"));

      const rejectBtn = document.createElement("button");
      rejectBtn.type = "button";
      rejectBtn.className = "btn-danger";
      rejectBtn.innerHTML = "❌ Reject"; // Emoji add kiya
      rejectBtn.style.padding = "5px 12px";
      rejectBtn.addEventListener("click", () => processOrder(orderId, "reject"));

      actionCell.appendChild(approveBtn);
      actionCell.appendChild(rejectBtn);
      row.appendChild(actionCell);
      tbody.appendChild(row);
    });
  } catch (err) {
    tbody.innerHTML = '<tr><td colspan="7" class="text-center title-danger">Failed to load orders.</td></tr>';
  }
}

export function processOrder(orderId, mode) {
  openOrderConfirmation(mode, async () => {
    Core.showLoader(`Processing order ${mode}...`);

    try {
      const result = await Core.requestJson(`/api/admin/orders/${mode}/${orderId}`, {
        method: "POST",
        headers: Core.getAuthHeader(),
        body: {}
      });

      Core.hideLoader();
      if (Core.handleAdminAuthFailure(result.status)) return;
      if (!result.ok) {
        Core.showMessage(Core.extractErrorMessage(result.data, "Failed to process order."), "error");
        return;
      }

      if (mode === "approve" && result.data && result.data.key) {
        Core.showMessage(`Order approved for ${result.data.username}. Key: ${result.data.key}`, "success");
      } else {
        Core.showMessage(result.data.message || `Order ${mode}d successfully.`, "success");
      }

      await loadPendingOrders();
    } catch (err) {
      Core.hideLoader();
      Core.showMessage("Server error while processing the order.", "error");
    }
  });
}

export async function handleCreateAdmin() {
  const username = String(document.getElementById("newAdminUsername")?.value || "").trim().toLowerCase();
  const password = document.getElementById("newAdminPassword")?.value || "";

  if (!username || !password) {
    Core.showMessage("Username and password are required.", "error");
    return;
  }

  if (password.length < 6) {
    Core.showMessage("Admin passwords must be at least 6 characters long.", "error");
    return;
  }

  Core.showLoader("Creating admin...");

  try {
    const isOwner = await verifyOwnerAccess(true);
    if (!isOwner) {
      Core.hideLoader();
      Core.showMessage("Only the verified owner can create admins.", "error");
      return;
    }

    const result = await Core.requestJson("/api/admin/create-admin", {
      method: "POST",
      headers: Core.getAuthHeader(),
      body: { username, password }
    });

    Core.hideLoader();
    if (Core.handleAdminAuthFailure(result.status)) return;
    if (!result.ok) {
      Core.showMessage(Core.extractErrorMessage(result.data, "Failed to create admin."), "error");
      return;
    }

    document.getElementById("createAdminForm")?.reset();
    closeModal("createAdminModal");
    Core.showMessage(`Admin ${username} created successfully.`, "success");
  } catch (err) {
    Core.hideLoader();
    Core.showMessage(Core.isAbortError(err) ? "Request timed out. Try again." : "Server error.", "error");
  }
}

export async function handleAdminPasswordChange() {
  const currentPassword = document.getElementById("adminOldPass")?.value || "";
  const newPassword = document.getElementById("adminNewPass")?.value || "";

  if (!currentPassword || !newPassword) {
    Core.showMessage("Current and new password are required.", "error");
    return;
  }

  if (newPassword.length < 6) {
    Core.showMessage("Admin passwords must be at least 6 characters long.", "error");
    return;
  }

  if (currentPassword === newPassword) {
    Core.showMessage("New password must be different from the current password.", "error");
    return;
  }

  Core.showLoader("Updating password...");

  try {
    const result = await Core.requestJson("/api/admin/change-password", {
      method: "POST",
      headers: Core.getAuthHeader(),
      body: { currentPassword, newPassword }
    });

    Core.hideLoader();
    if (Core.handleAdminAuthFailure(result.status)) return;
    if (!result.ok) {
      Core.showMessage(Core.extractErrorMessage(result.data, "Failed to update admin password."), "error");
      return;
    }

    document.getElementById("adminChangePassForm")?.reset();
    closeModal("adminPassModal");
    Core.showMessage("Admin password updated successfully.", "success");
  } catch (err) {
    Core.hideLoader();
    Core.showMessage("Please Check Your Internet.", "error");
  }
}

export function bindDashboardControls() {
  document.getElementById("adminEditForm")?.addEventListener("submit", (event) => {
    event.preventDefault();
    saveUserEdit();
  });
  document.getElementById("refreshUsersBtn")?.addEventListener("click", () => loadAdminDash());
  document.getElementById("refreshOrdersBtn")?.addEventListener("click", () => loadPendingOrders());
  document.getElementById("openCreateAdminBtn")?.addEventListener("click", () => openModal("createAdminModal"));
  document.getElementById("openAdminPassBtn")?.addEventListener("click", () => openModal("adminPassModal"));
  document.getElementById("createAdminForm")?.addEventListener("submit", (event) => {
    event.preventDefault();
    handleCreateAdmin();
  });
  document.getElementById("adminChangePassForm")?.addEventListener("submit", (event) => {
    event.preventDefault();
    handleAdminPasswordChange();
  });
}
